-- Adds leave.approve and holidays.manage to the built-in roles of existing tenants.
UPDATE roles SET permissions = ARRAY['tenant.settings.read', 'tenant.settings.manage', 'entities.read', 'entities.manage', 'users.read', 'users.manage', 'roles.read', 'roles.manage', 'audit.read', 'employees.read', 'employees.manage', 'locations.read', 'locations.manage', 'schedules.read', 'schedules.manage', 'leave.approve', 'holidays.manage']::text[] WHERE is_system AND key = 'tenant_admin';--> statement-breakpoint
UPDATE roles SET permissions = ARRAY['tenant.settings.read', 'entities.read', 'users.read', 'users.manage', 'audit.read', 'employees.read', 'employees.manage', 'locations.read', 'schedules.read', 'leave.approve', 'holidays.manage']::text[] WHERE is_system AND key = 'hr';--> statement-breakpoint
UPDATE roles SET permissions = ARRAY['users.read', 'employees.read', 'locations.read', 'schedules.read', 'schedules.manage', 'leave.approve']::text[] WHERE is_system AND key = 'supervisor';--> statement-breakpoint
UPDATE roles SET permissions = '{}'::text[] WHERE is_system AND key = 'employee';
